<template>
  <main class="duel-view">
    <header class="page-head"><button class="back" @click="router.push('/lobby')">← Lobby</button><div><span class="kicker">Modalidad II</span><h1>Reto de 10</h1><p>Las mismas diez preguntas para ambos jugadores, sin esperar turnos.</p></div><div class="record"><small>Récord</small><strong>{{ wins }} G · {{ losses }} P · {{ ties }} E</strong></div></header>

    <section v-if="sessionQuestions.length" class="quiz-shell">
      <div class="quiz-top"><span>{{ sessionRole==='challenger'?'Creando reto':`Reto de ${activeDuel?.challengerName}` }}</span><strong>{{ currentIndex+1 }}/{{ sessionQuestions.length }}</strong></div><div class="progress"><span :style="{width:`${((currentIndex+1)/sessionQuestions.length)*100}%`}"></span></div>
      <article v-if="currentQuestion" class="question-card"><div class="badges"><span>{{ shortRite(sessionRite) }}</span><span>{{ currentQuestion.category }}</span></div><QuestionMedia :question="currentQuestion" /><h2>{{ currentQuestion.text }}</h2><button v-for="(option,index) in currentQuestion.options" :key="option" class="option" @click="answer(index)"><b>{{ String.fromCharCode(65+index) }}</b>{{ option }}</button></article>
      <div class="live-score">Aciertos hasta ahora: <strong>{{ liveScore }}</strong></div>
    </section>

    <template v-else>
      <section class="create-panel">
        <div class="create-title"><span class="kicker">Nuevo desafío</span><h2>Encuentra un rival</h2><p>Kabbalah y Cultura General están abiertas a todos.</p></div>
        <label>Rival<select v-model="setup.opponentUid"><option value="__random__">🎲 Rival aleatorio</option><option v-for="player in players" :key="player.uid" :value="player.uid">{{ player.name }}{{ player.degree?` · ${player.degree}`:'' }}</option></select></label>
        <label>Banco<select v-model="setup.rite" @change="syncLevel"><option v-for="rite in playableRites" :key="rite.value" :value="rite.value">{{ rite.label }}</option></select></label>
        <label v-if="!isOpenKnowledgeBank(setup.rite)">Nivel<select v-model="setup.level"><option value="aprendiz">Aprendiz</option><option value="compañero">Compañero</option><option value="maestro">Maestro</option></select></label>
        <div class="access-note" :class="{blocked:setupNeedsExam}"><span v-if="setup.rite==='kabala'">✦ Kabbalah · libre y sin reteje.</span><span v-else-if="setup.rite==='libre'">⚠ Cultura general · modo no masón.</span><span v-else-if="setupNeedsExam">🔐 Necesitas aprobar el examen de acceso para este banco/nivel.</span><span v-else>✓ Tu perfil puede usar este banco.</span></div>
        <button class="primary" :disabled="players.length===0" @click="startChallenge">{{ setupNeedsExam?'Hacer reteje':'Responder mis 10 preguntas' }}</button>
      </section>

      <section class="duel-columns">
        <div class="duel-list"><div class="list-head"><span class="kicker">Pendientes</span><h2>Retos recibidos</h2></div><div v-if="!incoming.length" class="empty">No tienes retos pendientes.</div><article v-for="duel in incoming" :key="duel.id" class="duel-row"><div><strong>{{ duel.challengerName }}</strong><small>{{ shortRite(duel.rite) }} · {{ levelLabel(duel.level) }} · {{ duel.challengerScore }}/10</small></div><button class="primary small" @click="openDuel(duel.id)">Responder</button></article></div>
        <div class="duel-list"><div class="list-head"><span class="kicker">Historial</span><h2>Resultados</h2></div><div v-if="!finished.length" class="empty">Todavía no tienes partidas terminadas.</div><article v-for="duel in finished" :key="duel.id" class="duel-row"><div><strong>{{ opponentName(duel) }}</strong><small>{{ duel.challengerName }} {{ duel.challengerScore }} – {{ duel.opponentScore }} {{ duel.opponentName }}</small></div><span class="result-chip" :class="resultClass(duel)">{{ resultLabel(duel) }}</span></article></div>
      </section>
    </template>
    <div v-if="message" class="toast">{{ message }}</div>
  </main>
</template>

<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import QuestionMedia from '@/modules/questions/QuestionMedia.vue'
import { useAuthStore } from '@/stores/authStore';import { useAccessStore } from '@/stores/accessStore';import { useQuestionsStore } from '@/stores/questionsStore'
import { duelService } from '@/modules/game/duels/duelService';import type { Duel,DuelPlayerOption } from '@/modules/game/duels/duelService'
import { requiresAccessExam } from '@/modules/game/access/riteAccess';import type { RoomLevel } from '@/modules/game/access/riteAccess'
import { DEGREE_LABELS,isOpenKnowledgeBank,MASONIC_RITES,RITE_SHORT_LABELS } from '@/modules/questions/questionRules';import type { MasonicRite,Question } from '@/modules/questions/types'

const router=useRouter(),route=useRoute(),authStore=useAuthStore(),accessStore=useAccessStore(),questionsStore=useQuestionsStore();const players=ref<DuelPlayerOption[]>([]),duels=ref<Duel[]>([]),message=ref(''),sessionQuestions=ref<Question[]>([]),currentIndex=ref(0),liveScore=ref(0),activeDuel=ref<Duel|null>(null),sessionRite=ref<MasonicRite>('reaa');const sessionRole=ref<'challenger'|'opponent'>('challenger');let unsubscribe:(()=>void)|null=null
const playableRites=MASONIC_RITES.filter(r=>r.value!=='otro');const setup=reactive<{opponentUid:string;rite:MasonicRite;level:RoomLevel}>({opponentUid:'__random__',rite:'reaa',level:authStore.masonicDegree??'aprendiz'});const preferredRite=computed(()=>accessStore.preferredRite??'reaa');const currentQuestion=computed(()=>sessionQuestions.value[currentIndex.value]??null);const incoming=computed(()=>duels.value.filter(d=>d.status==='pending'&&d.opponentUid===authStore.currentUser?.uid));const finished=computed(()=>duels.value.filter(d=>d.status==='finished'));const wins=computed(()=>finished.value.filter(d=>d.winnerUid===authStore.currentUser?.uid).length);const losses=computed(()=>finished.value.filter(d=>d.winnerUid&&d.winnerUid!=='tie'&&d.winnerUid!==authStore.currentUser?.uid).length);const ties=computed(()=>finished.value.filter(d=>d.winnerUid==='tie').length);const setupNeedsExam=computed(()=>requiresAccessExam(preferredRite.value,authStore.masonicDegree,setup.rite,setup.level,accessStore.certificationFor(setup.rite)))
onMounted(async()=>{if(!authStore.currentUser)return;await Promise.all([questionsStore.loadQuestions({fallbackToDefaults:true}),accessStore.loadForUser(authStore.currentUser.uid)]);players.value=await duelService.listPlayers(authStore.currentUser.uid);unsubscribe=duelService.subscribeForUser(authStore.currentUser.uid,items=>{duels.value=items});const id=route.query.duel as string|undefined;if(id)await openDuel(id)});onBeforeUnmount(()=>unsubscribe?.())
const shortRite=(rite:MasonicRite)=>RITE_SHORT_LABELS[rite];const levelLabel=(level:RoomLevel)=>level==='general'?'General':DEGREE_LABELS[level];const syncLevel=()=>{setup.level=isOpenKnowledgeBank(setup.rite)?'general':(authStore.masonicDegree??'aprendiz')};const shuffle=<T,>(items:T[])=>[...items].sort(()=>Math.random()-.5);const chooseOpponent=()=>setup.opponentUid==='__random__'?players.value[Math.floor(Math.random()*players.value.length)]??null:players.value.find(p=>p.uid===setup.opponentUid)??null
const startChallenge=async()=>{if(setupNeedsExam.value){router.push({path:'/reteje',query:{rite:setup.rite,level:setup.level,returnTo:'/duels'}});return}const opponent=chooseOpponent();if(!opponent){message.value='No hay otro usuario disponible.';return}setup.opponentUid=opponent.uid;const pool=questionsStore.getQuestionsForRoom(setup.rite,setup.level,undefined,'duel');if(pool.length<10){message.value='Este banco todavía no tiene 10 preguntas habilitadas para 1vs1.';return}sessionQuestions.value=shuffle(pool).slice(0,10);sessionRite.value=setup.rite;currentIndex.value=0;liveScore.value=0;sessionRole.value='challenger';message.value=`Rival asignado: ${opponent.name}.`}
const openDuel=async(id:string)=>{const duel=await duelService.getDuel(id);if(!duel||duel.opponentUid!==authStore.currentUser?.uid||duel.status!=='pending')return;await questionsStore.loadQuestions({fallbackToDefaults:true});const questions=duel.questionIds.map(id=>questionsStore.questions.find(q=>q.id===id)).filter((q):q is Question=>Boolean(q));if(questions.length!==duel.questionIds.length){message.value='No se pudieron recuperar todas las preguntas.';return}activeDuel.value=duel;sessionQuestions.value=questions;sessionRite.value=duel.rite;currentIndex.value=0;liveScore.value=0;sessionRole.value='opponent'}
const answer=async(optionIndex:number)=>{const question=currentQuestion.value;if(!question)return;const nextScore=liveScore.value+(optionIndex===question.correctAnswer?1:0);liveScore.value=nextScore;if(currentIndex.value<sessionQuestions.value.length-1){currentIndex.value+=1;return}const score=nextScore;if(sessionRole.value==='challenger'){if(!authStore.currentUser||!authStore.profile)return;const opponent=players.value.find(p=>p.uid===setup.opponentUid);if(!opponent)return;await duelService.createDuel({challengerUid:authStore.currentUser.uid,challengerName:authStore.profile.name,opponentUid:opponent.uid,opponentName:opponent.name,rite:setup.rite,level:setup.level,questionIds:sessionQuestions.value.map(q=>q.id),challengerScore:score});message.value=`Reto enviado a ${opponent.name}: ${score} correctas y ${10-score} incorrectas.`;setup.opponentUid='__random__'}else if(activeDuel.value){await duelService.finishDuel(activeDuel.value,score);message.value=score>activeDuel.value.challengerScore?`Ganaste ${score} a ${activeDuel.value.challengerScore}.`:score<activeDuel.value.challengerScore?`Perdiste ${score} a ${activeDuel.value.challengerScore}.`:`Empate ${score} a ${score}.`}sessionQuestions.value=[];currentIndex.value=0;liveScore.value=0;activeDuel.value=null;router.replace('/duels')}
const opponentName=(d:Duel)=>d.challengerUid===authStore.currentUser?.uid?d.opponentName:d.challengerName;const resultLabel=(d:Duel)=>d.winnerUid==='tie'?'Empate':d.winnerUid===authStore.currentUser?.uid?'Ganaste':'Perdiste';const resultClass=(d:Duel)=>d.winnerUid==='tie'?'tie':d.winnerUid===authStore.currentUser?.uid?'win':'loss'
</script>

<style scoped>
