rder-radius:99px;font-size:9px;font-weight:900}.win{color:#91d3a1}.loss{color:#e99b97}.tie{color:#ddc982}.quiz-shell{margin-top:23px}.quiz-top{display:flex;justify-content:space-between}.progress{height:5px;margin:9px 0 14px;background:rgba(255,255,255,.06)}.progress span{display:block;height:100%;background:#c9a84c}.question-card{padding:20px;border:1px solid rgba(214,183,95,.3);border-radius:14px;background:rgba(8,22,36,.88)}.badges{display:flex;gap:6px;margin-bottom:10px}.badges span{font-size:9px;padding:5px 8px;border-radius:99px;background:rgba(214,183,95,.09);color:#ddc47c}.question-card h2{color:#f0e2c5;line-height:1.4}.option{width:100%;display:grid;grid-template-columns:32px 1fr;gap:9px;margin:7px 0;padding:11px;text-align:left;border:1px solid rgba(214,183,95,.2);border-radius:8px;background:rgba(255,255,255,.025);color:#efe1c4}.option:hover{border-color:#c9a84c}.option b{color:#dfc36c}.live-score{text-align:right;margin-top:9px;color:rgba(238,224,194,.53)}.live-score strong{color:#e3ca76}.toast{position:fixed;right:18px;bottom:18px;max-width:430px;padding:12px 15px;border:1px solid #c9a84c;border-radius:10px;background:#0a1724;color:#eadba9;box-shadow:0 12px 35px #000}@media(max-width:850px){.create-panel{grid-template-columns:1fr 1fr}.access-note{grid-column:1/-1}.duel-columns{grid-template-columns:1fr}}@media(max-width:560px){.page-head,.create-panel{grid-template-columns:1fr}.record{text-align:left}}
</style>
